-- 2. المقال الأول: الوظائف الأكثر طلباً
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'الوظائف الأكثر طلباً في المغرب 2026: أين تبحث؟', 'wadifa-maghreb-2026',
'دليلك لفهم سوق العمل المغربي في 2026 وأفضل القطاعات التي توفر فرص حقيقية للتوظيف.',
E'# الوظائف الأكثر طلباً في المغرب 2026\n\nسوق العمل المغربي يتغير بسرعة. كأس العالم 2030 قريب، والشركات الكبرى تستثمر مليارات. هذا يعني فرص جديدة لكن أيضاً منافسة شديدة.\n\nفي هاد المقال غادي نوريك فين كاين الخدمة بصح في 2026، شنو التخصصات اللي كتطلبها الشركات، وكيفاش تقدر تحضر راسك.\n\n## القطاعات الأكثر طلباً\n\n### 1. قطاع السيارات\n\nالمغرب صار أكبر منتج للسيارات في أفريقيا. الشركات كبر Renault و Stellantis عندهم مصانع كبيرة في الدار البيضاء وطنجة.\n\n**شنو كيطلبو:** مهندسين ميكانيكيين، عمال لحام، تقنيين للجودة\n\n**الرواتب:** من 5000 ل 25000 درهم حسب الخبرة\n\n### 2. تكنولوجيا المعلومات\n\nالحكومة كتستهدف 50,000 وظيفة في IT بحلول 2026. الشركات كتعطي رواتب مغرية للمطورين.\n\n**التخصصات المطلوبة:** تطوير الويب (React, Python)، الأمن السيبراني، تحليل البيانات\n\n### 3. قطاع البناء\n\nكأس العالم 2030 خلاّ الطلب على عمال البناء يطلع. الاستادات والفنادق الجديدة تحتاج مئات الآلاف من العمال.\n\n### 4. قطاع الطاقة المتجددة\n\nالمغرب يقود إفريقياً في مشاريع الطاقة الشمسية. فيه طلب كبير على مهندسي الطاقة المتجددة.\n\n## كيفاش تحضر راسك؟\n\n1. **تعلم مهارة جديدة:** شوف شنو التخصص اللي كيطلب ويتعلمها\n2. **احصل على شهادة:** الشهادات المعتمدة كتفرق معاك\n3. **كون عملي:** الشركة كتفضل اللي عندو خبرة عملية\n\n## خلاصة\n\nسوق العمل المغربي فيه فرص بزاف، لكن لازم تكون ذكي وكيفاش تختار.\n\n**اقرأ أيضاً:** [كيفية كتابة سيرة ذاتية احترافية](/article/kitaba-sirat-dhatia) | [استعداد للمقابلة الوظيفية](/article/i-dad-muqabala-wazifiya)',
'<h2>الوظائف الأكثر طلباً في المغرب 2026</h2><p>سوق العمل المغربي يتغير بسرعة. كأس العالم 2030 قريب، والشركات الكبرى تستثمر مليارات.</p><h3>1. قطاع السيارات</h3><p>المغرب صار أكبر منتج للسيارات في أفريقيا. الرواتب: من 5000 ل 25000 درهم.</p><h3>2. تكنولوجيا المعلومات</h3><p>الحكومة كتستهدف 50,000 وظيفة في IT.</p><h3>3. قطاع البناء</h3><p>كأس العالم 2030 خلاّ الطلب على عمال البناء يطلع.</p><h3>4. قطاع الطاقة المتجددة</h3><p>المغرب يقود إفريقياً في مشاريع الطاقة الشمسية.</p><p><strong>اقرأ أيضاً:</strong> كيفية كتابة سيرة ذاتية | استعداد للمقابلة</p>',
'published', NOW(),
'الوظائف الأكثر طلباً في المغرب 2026 | دليل شامل',
'اكتشف أبرز الوظائف والقطاعات الأكثر طلباً في المغرب لسنة 2026. دليل يشمل الرواتب والمؤهلات.',
7, (SELECT id FROM categories WHERE slug = 'job-market' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'wadifa-maghreb-2026');

-- 3. المقال الثاني: كتابة السيرة الذاتية
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'كيفية كتابة سيرة ذاتية احترافية تلفت انتباه المُوظِّف', 'kitaba-sirat-dhatia',
'خطوة بخطوة: كيفاش تكتب سيرة ذاتية قوية تخليك تختلف على المترشحين الآخرين.',
E'# كيفية كتابة السيرة الذاتية\n\nكتكتب سيرة ذاتية وكتبعثها للشركات ومكت responded. علاش؟ لأنو السيرة الذاتية ديالك ماشي قوية بزاف.\n\nفي هاد المقال غادي نعلمك كيفاش تكتب سيرة ذاتية تلفت انتباه المُوظِّف من أول ثانية.\n\n## شنو هي السيرة الذاتية المثالية؟\n\n- مختصرة (صفحة واحدة للخبرة القليلة)\n- واضحة ومنظمة\n- كتبرز نقاط قوتك\n- مكتوبة بشكل احترافي\n\n## الأقسام الأساسية\n\n### 1. المعلومات الشخصية\nالاسم الكامل، رقم الهاتف، البريد الإلكتروني المهني، المدينة\n\n### 2. الملف الشخصي\nفقرة قصيرة عنك (3-4 جمل) تشرح شنو تخصصك وهدفك المهني\n\n### 3. الخبرات العملية\nابدأ بالخبرة الأخيرة، واذكر اسم الشركة والمسمى الوظيفي، و3-4 مهام قمت بها\n\n### 4. التكوين والتعليم\nالشهادة + الجامعة + السنة، الدورات التدريبية المهمة\n\n### 5. المهارات\nمهارات تقنية (برامج، لغات برمجة) ومهارات شخصية (قيادة، تواصل)\n\n## نصائح ذهبية\n\n- **لا تكذب:** الكذب ممكن يضرك أكثر ما ينفعك\n- **خصصها لكل وظيفة:** كل وظيفة تحتاج سيرة ذاتية مختلفة\n- **راجع الأخطاء الإملائية:** الخطأ الإملائي يعطي انطباع سيء\n- **استخدم PDF:** لا تبعت Word\n\n## قوالب مجانية\n\n- Canva\n- Novoresume\n- Zety\n\n**اقرأ أيضاً:** [الوظائف الأكثر طلباً](/article/wadifa-maghreb-2026) | [استعداد للمقابلة](/article/i-dad-muqabala-wazifiya)',
'<h2>كيفية كتابة السيرة الذاتية</h2><p>كتكتب سيرة ذاتية وكتبعثها للشركات ومكت responded.</p><h3>الأقسام الأساسية</h3><ul><li>المعلومات الشخصية</li><li>الملف الشخصي</li><li>الخبرات العملية</li><li>التكوين والتعليم</li><li>المهارات</li></ul><h3>نصائح ذهبية</h3><ol><li>لا تكذب</li><li>خصصها لكل وظيفة</li><li>راجع الأخطاء الإملائية</li><li>استخدم PDF</li></ol><p><strong>اقرأ أيضاً:</strong> الوظائف الأكثر طلباً | استعداد للمقابلة</p>',
'published', NOW(),
'كيفية كتابة سيرة ذاتية احترافية للمغرب | دليل شامل',
'تعلم كيفاش تكتب سيرة ذاتية قوية تلفت انتباه المُوظِّف.',
6, (SELECT id FROM categories WHERE slug = 'self-development' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'kitaba-sirat-dhatia');

-- 4. المقال الثالث: استعداد للمقابلة
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'كيفاش تحضر راسك للمقابلة الوظيفية وتنجح', 'i-dad-muqabala-wazifiya',
'نصائح عملية للتغلب على التوتر والظهور بأفضل صورة أثناء المقابلة الوظيفية.',
E'# كيفاش تحضر راسك للمقابلة الوظيفية\n\nالمقابلة الوظيفية كتبقى أصعب مرحلة في البحث عن الخدمة. حتى لو عندك سيرة ذاتية قوية، المقابلة هي اللي كتحدد واش غادي تتقبل ولا لا.\n\n## قبل المقابلة\n\n### 1. ابحث عن الشركة\n- شوف شنو هي نشاط الشركة\n- اعرف المدير الموارد البشرية\n- شوف آخر الأخبار على الموقع ديالهم\n\n### 2. حضر إجاباتك\n- "عرف راسك" (30 ثانية)\n- "علاش هاد الشركة؟"\n- "شنو نقاط قوتك وضعفك؟"\n- "وين شايف راسك بعد 5 سنوات؟"\n\n### 3. اختر اللبس المناسب\n- لبس رسمي أو شبه رسمي\n- نظيف ومكوي\n\n## أثناء المقابلة\n\n- **كون في الوقت:** القدوم بكرا بـ 10 دقائق هو الأفضل\n- **ابتسام:** الابتسامة كتعطي انطباع إيجابي\n- **النظر في العيون:** كيبين الثقة بالنفس\n- **استمع جيداً:** لا تقاطع المُوظِّف\n\n## بعد المقابلة\n\n- أرسل رسالة شكر خلال 24 ساعة\n- اتصل بعد أسبوع إن لم تسمع أي خبر\n\n**اقرأ أيضاً:** [كيفية كتابة سيرة ذاتية](/article/kitaba-sirat-dhatia) | [الوظائف الأكثر طلباً](/article/wadifa-maghreb-2026)',
'<h2>كيفاش تحضر راسك للمقابلة الوظيفية</h2><p>المقابلة الوظيفية كتبقى أصعب مرحلة في البحث عن الخدمة.</p><h3>قبل المقابلة</h3><ul><li>ابحث عن الشركة</li><li>حضر إجاباتك</li><li>اختر اللبس المناسب</li></ul><h3>أثناء المقابلة</h3><ul><li>كون في الوقت</li><li>ابتسام</li><li>النظر في العيون</li></ul><p><strong>اقرأ أيضاً:</strong> كتابة السيرة الذاتية | الوظائف الأكثر طلباً</p>',
'published', NOW(),
'كيفاش تحضر راسك للمقابلة الوظيفية | نصائح عملية',
'نصائح عملية للتغلب على التوتر والظهور بأفضل صورة أثناء المقابلة الوظيفية.',
5, (SELECT id FROM categories WHERE slug = 'interviews' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'i-dad-muqabala-wazifiya');

-- 5. المقال الرابع: العمل الحر
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'العمل الحر في المغرب: كيفاش تبدا وتربح', 'al-amal-al-hur',
'دليل شامل للعمل الحر في المغرب: منصات العمل، المهارات المطلوبة، وكيفاش تبني مشوارك الحر.',
E'# العمل الحر في المغرب: كيفاش تبدا وتربح\n\nالعمل الحر صار خيار واقعي بزاف للمغاربة. بدل ما تنتظر الخدمة عند الغير، تقدر تخدم بحسابك وتكسب مبلغ مالي محترم.\n\n## شنو هو العمل الحر؟\n\nالعمل الحر هو أنك تقدم خدمات لشركات أو أشخاص بشكل مستقل، بدون ما تكون موظف عندهم.\n\n## أحسن المجالات للعمل الحر\n\n### 1. تطوير الويب والتطبيقات\nWordPress، React، Angular، تطبيقات الموبايل\n\n### 2. التصميم الجرافيكي\nتصميم الشعارات، تصميم السوشيال ميديا، تصميم المواقع\n\n### 3. كتابة المحتوى\nمقالات للويب، محتوى تسويقي، ترجمة\n\n### 4. التسويق الرقمي\nإدارة حسابات السوشيال ميديا، إعلانات Google، SEO\n\n## منصات العمل الحر\n\n- **Upwork:** أكبر منصة عالمية\n- **Fiverr:** منصة سهلة للمبتدئين\n- **Mostaql:** منصة عربية كبيرة\n\n## كيفاش تبدا؟\n\n1. حدد تخصصك\n2. ánمل ملف شخصي قوي\n3. ابدأ بثمن منخفض باش تجمع تقييمات\n4. كن صبور\n\n## نصائح للنجاح\n\n- الالتزام بالمواعيد كيبين الاحترافية\n- كن صريح مع العميل\n- الخدمة المزيانة كتجيب عملاء جدد\n\n**اقرأ أيضاً:** [الوظائف عن بُعد](/article/wadifa-an-bu-d) | [التسويق الرقمي](/article/taaswiiq-raqami)',
'<h2>العمل الحر في المغرب</h2><p>العمل الحر صار خيار واقعي بزاف للمغاربة.</p><h3>أحسن المجالات</h3><ul><li>تطوير الويب والتطبيقات</li><li>التصميم الجرافيكي</li><li>كتابة المحتوى</li><li>التسويق الرقمي</li></ul><h3>منصات العمل الحر</h3><ul><li>Upwork</li><li>Fiverr</li><li>Mostaql</li></ul><p><strong>اقرأ أيضاً:</strong> الوظائف عن بُعد | التسويق الرقمي</p>',
'published', NOW(),
'العمل الحر في المغرب: دليل شامل للمبتدئين',
'كيفاش تبدا العمل الحر في المغرب وتربح.',
8, (SELECT id FROM categories WHERE slug = 'freelancing-remote' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'al-amal-al-hur');

-- 6. المقال الخامس: الوظائف عن بُعد
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'الوظائف عن بُعد في المغرب: فرصة حقيقية أم خيال؟', 'wadifa-an-bu-d',
'هل تعلم أنه يمكنك العمل لصالح شركة أجنبية من المغرب؟ تعرف على فرص العمل عن بُعد ورواتبها.',
E'# الوظائف عن بُعد في المغرب: فرصة حقيقية أم خيال؟\n\nالعمل عن بُعد ماشي حلم، صار واقع. بزاف شركات عالمية كتوظف ناس من المغرب بدون ما يحتاجوهم يجيو للمكتب.\n\n## ليش العمل عن بُعد كينمو في المغرب؟\n\n1. **تكلفة المعيشة المنخفضة:** الشركة كتوفر على المكتب والمرافق\n2. **الكفاءات المغربية:** المغاربة معروفين بالجدية والمرونة\n3. **البنية التحتية الرقمية:** internet في المغرب صار مزيان\n4. **القرب من أوروبا:** المغرب قريب من أوروبا\n\n## أحسن الوظائف عن بُعد\n\n### 1. تطوير البرمجيات\nمطور ويب، مطور تطبيقات موبايل، مهندس DevOps\n\n### 2. التسويق الرقمي\nمسوّق عبر البريد الإلكتروني، مدير حسابات إعلانية، كاتب محتوى\n\n### 3. خدمة العملاء\nمستشار خدمة العملاء (بالفرنسية أو الإنجليزية)\n\n## الرواتب\n\n- **مطور ويب:** 8000 - 25,000 درهم\n- **مسوّق رقمي:** 6000 - 18,000 درهم\n- **خدمة عملاء:** 4000 - 8000 درهم\n\n## منصات البحث عن العمل عن بُعد\n\n- LinkedIn\n- Remote.co\n- We Work Remotely\n\n**اقرأ أيضاً:** [العمل الحر](/article/al-amal-al-hur) | [المهن التقنية](/article/mihn-taqniya)',
'<h2>الوظائف عن بُعد في المغرب</h2><p>العمل عن بُعد ماشي حلم، صار واقع.</p><h3>أحسن الوظائف عن بُعد</h3><ul><li>تطوير البرمجيات</li><li>التسويق الرقمي</li><li>خدمة العملاء</li></ul><h3>الرواتب</h3><ul><li>مطور ويب: 8000 - 25,000 درهم</li><li>مسوّق رقمي: 6000 - 18,000 درهم</li></ul><p><strong>اقرأ أيضاً:</strong> العمل الحر | المهن التقنية</p>',
'published', NOW(),
'الوظائف عن بُعد في المغرب 2026 | فرص حقيقية',
'هل يمكنك العمل لصالح شركة أجنبية من المغرب؟',
6, (SELECT id FROM categories WHERE slug = 'freelancing-remote' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'wadifa-an-bu-d');

-- 7. المقال السادس: قطاع البنوك
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'التوظيف في قطاع البنوك والتأمين بالمغرب', 'tawzif-bunuk',
'دليل شامل للتوظيف في قطاع البنوك والتأمين: المسميات الوظيفية، المؤهلات، والرواتب.',
E'# التوظيف في قطاع البنوك والتأمين بالمغرب\n\nقطاع البنوك والتأمين من أكثر القطاعات استقراراً في المغرب. فيه فرص بزاف للمغاربة اللي عندهم المؤهلات المناسبة.\n\n## المسميات الوظيفية المتاحة\n\n### في البنوك\n- موظف استقبال: أول وجه يشوفه الزبون\n- مستشار التمويل: ينصح الزبائن بالمنتجات المالية\n- محاسب: مسؤول عن الحسابات\n- مدير فرع: يدير فرع البنك\n\n### في شركات التأمين\n- وسيط التأمين: يبيع وثائق التأمين\n- خبير تأمين: يقيّم المخاطر\n- مسؤول التعويضات: يعالج مطالبات الزبائن\n\n## المؤهلات المطلوبة\n\n- شهادة في التمويل أو المحاسبة\n- شهادة في التأمين (معتمدة)\n- الإجازة في إدارة الأعمال\n\n## الرواتب\n\n- موظف استقبال: 4000 - 6000 درهم\n- مستشار: 6000 - 10,000 درهم\n- محاسب: 8000 - 15,000 درهم\n- مدير فرع: 15,000 - 30,000 درهم\n\n## نصائح للنجاح\n\n- كون دقيق: الخطأ في البنك كيكون غالي الثمن\n- اتقن Excel: أساسي في هاد القطاع\n- تعلم أنظمة الدفع الإلكتروني\n\n**اقرأ أيضاً:** [الوظائف الأكثر طلباً](/article/wadifa-maghreb-2026) | [كتابة السيرة الذاتية](/article/kitaba-sirat-dhatia)',
'<h2>التوظيف في قطاع البنوك والتأمين</h2><h3>المسميات الوظيفية</h3><ul><li>موظف استقبال</li><li>مستشار التمويل</li><li>محاسب</li><li>مدير فرع</li></ul><h3>الرواتب</h3><ul><li>موظف استقبال: 4000 - 6000 درهم</li><li>مستشار: 6000 - 10,000 درهم</li><li>محاسب: 8000 - 15,000 درهم</li><li>مدير فرع: 15,000 - 30,000 درهم</li></ul><p><strong>اقرأ أيضاً:</strong> الوظائف الأكثر طلباً | كتابة السيرة الذاتية</p>',
'published', NOW(),
'التوظيف في قطاع البنوك والتأمين بالمغرب',
'دليل شامل للتوظيف في قطاع البنوك والتأمين في المغرب.',
