-- 8. المقال السابع: قطاع السياحة
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'التوظيف في قطاع السياحة والضيافة بالمغرب', 'tawzif-siyaha',
'مع استعدادات كأس العالم 2030، قطاع السياحة يعيش طفرة كبيرة. تعرف على فرص العمل والرواتب.',
E'# التوظيف في قطاع السياحة والضيافة بالمغرب\n\nالمغرب من أكتر الدول السياحية في أفريقيا. في 2025، زار المغرب أكثر من 15 مليون سائح. وكأس العالم 2030 غادي يزيد هاد العدد بزاف.\n\n## ليش قطاع السياحة مهم؟\n\n- مصدر ربح كبير: السياحة كتساهم في 7% من الناتج المحلي\n- خلق فرص عمل: أكثر من مليون وظيفة مباشرة وغير مباشرة\n\n## المسميات الوظيفية\n\n### في الفنادق\n- نادل: خدمة الزبائن في المطاعم\n- موظف استقبال: أول وجه يشوفه النزيل\n- طبّاخ: إعداد الوجبات\n- مدير فندق: إدارة الفندق بالكامل\n\n### في وكالات السفر\n- مرشد سياحي: يرشد الزوار\n- مسؤول الحجز: يدير حجوزات الفنادق والطيران\n\n## الرواتب\n\n- نادل: 2500 - 4000 درهم\n- موظف استقبال: 3500 - 6000 درهم\n- طبّاخ: 4000 - 8000 درهم\n- مرشد سياحي: 5000 - 10,000 درهم\n- مدير فندق: 12,000 - 30,000 درهم\n\n## نصائح للنجاح\n\n- كون لطيف مع الزبائن\n- اتقن لغة أجنبية\n- تعلم التعامل مع الضغط\n\n**اقرأ أيضاً:** [الوظائف الأكثر طلباً](/article/wadifa-maghreb-2026) | [العمل الحر](/article/al-amal-al-hur)',
'<h2>التوظيف في قطاع السياحة والضيافة</h2><h3>المسميات الوظيفية</h3><ul><li>نادل</li><li>موظف استقبال</li><li>طبّاخ</li><li>مدير فندق</li></ul><h3>الرواتب</h3><ul><li>نادل: 2500 - 4000 درهم</li><li>موظف استقبال: 3500 - 6000 درهم</li><li>مدير فندق: 12,000 - 30,000 درهم</li></ul><p><strong>اقرأ أيضاً:</strong> الوظائف الأكثر طلباً | العمل الحر</p>',
'published', NOW(),
'التوظيف في قطاع السياحة والضيافة بالمغرب 2026',
'مع استعدادات كأس العالم 2030، قطاع السياحة يعيش طفرة.',
