-- 9. المقال الثامن: المهن التقنية
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'المهن التقنية في المغرب: دليلك لبناء مستقبل رقمي ناجح', 'mihn-taqniya',
'قطاع التقنية في المغرب ينمو بسرعة. تعرف على أفضل المهن التقنية والمهارات المطلوبة والرواتب.',
E'# المهن التقنية في المغرب\n\nالقطاع التقني في المغرب من أسرع القطاعات نمواً. الشركات كتحتاج مطورين ومحللين ومهندسين بزاف.\n\n## ليش المهن التقنية مطلوبة؟\n\n1. التحول الرقمي: كل الشركات كتتحول للرقمي\n2. Offshoring: شركات عالمية كتوظف في المغرب\n3. Startups: الشركات الناشئة كتنمو بسرعة\n\n## أفضل المهن التقنية\n\n### 1. مطور الويب\n- Frontend: React, Vue, Angular\n- Backend: Node.js, Python, PHP\n- الرواتب: 8000 - 25,000 درهم\n\n### 2. مطور تطبيقات الموبايل\n- Android: Kotlin, Java\n- iOS: Swift\n- Cross-platform: Flutter, React Native\n- الرواتب: 10,000 - 30,000 درهم\n\n### 3. مهندس DevOps\n- الأدوات: Docker, Kubernetes, AWS\n- الرواتب: 15,000 - 35,000 درهم\n\n### 4. محلل الأمن السيبراني\n- الشهادات: CISSP, CEH\n- الرواتب: 12,000 - 30,000 درهم\n\n## المنصات المجانية للتعلم\n\n- FreeCodeCamp: تعلم الويب مجاناً\n- Coursera: دورات من جامعات عالمية\n- Udemy: دورات عملية\n\n## نصائح للنجاح\n\n- اشتغل على مشاريع حقيقية\n- شارك في المجتمعات التقنية\n- اتقن الإنجليزية\n\n**اقرأ أيضاً:** [الوظائف عن بُعد](/article/wadifa-an-bu-d) | [التسويق الرقمي](/article/taaswiiq-raqami)',
'<h2>المهن التقنية في المغرب</h2><h3>مطور الويب</h3><p>Frontend: React, Vue | Backend: Node.js, Python</p><p>الرواتب: 8000 - 25,000 درهم</p><h3>مطور تطبيقات الموبايل</h3><p>Flutter, React Native, Kotlin</p><p>الرواتب: 10,000 - 30,000 درهم</p><h3>مهندس DevOps</h3><p>Docker, Kubernetes, AWS</p><p>الرواتب: 15,000 - 35,000 درهم</p><p><strong>اقرأ أيضاً:</strong> الوظائف عن بُعد | التسويق الرقمي</p>',
'published', NOW(),
'المهن التقنية في المغرب 2026 | دليل شامل',
'قطاع التقنية في المغرب ينمو بسرعة.',
8, (SELECT id FROM categories WHERE slug = 'self-development' LIMIT 1), (SELECT id FROM users WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug = 'mihn-taqniya');

-- 10. المقال التاسع: التسويق الرقمي
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'التسويق الرقمي في المغرب: كيفاش تبني مهارة مطلوبة بزاف', 'taaswiiq-raqami',
'التسويق الرقمي صار من أهم المهارات في 2026. تعرف على التخصصات والمنصات والرواتب.',
E'# التسويق الرقمي في المغرب\n\nالتسويق الرقمي ماشي بس نشر صور على Instagram. فيه تخصصات بزاف والشركات كتدفع بزاف باش تلقى ناس يعرفو يديرو التسويق مزيان.\n\n## شنو هو التسويق الرقمي؟\n\n- الإعلانات المدفوعة (Google Ads, Facebook Ads)\n- التسويق عبر المحتوى\n- التسويق عبر البريد الإلكتروني\n- تحسين محركات البحث (SEO)\n- إدارة وسائل التواصل الاجتماعي\n\n## تخصصات التسويق الرقمي\n\n### 1. مدير حسابات إعلانية\nيدير إعلانات Google وFacebook - الرواتب: 8000 - 20,000 درهم\n\n### 2. خبير SEO\nيحسن ترتيب المواقع في Google - الرواتب: 10,000 - 25,000 درهم\n\n### 3. كاتب المحتوى\nيكتب مقالات وأوصاف للمنتجات - الرواتب: 4000 - 10,000 درهم\n\n### 4. مدير وسائل التواصل الاجتماعي\nيدير حسابات Instagram, Facebook, TikTok - الرواتب: 5000 - 15,000 درهم\n\n## كيفاش تتعلم؟\n\n- Google Digital Garage: شهادة مجانية من Google\n- HubSpot Academy: دورات inbound marketing\n- Meta Blueprint: تعلم إعلانات Facebook\n\n## نصائح للنجاح\n\n- اشتغل على مشاريع حقيقية\n- تتبع الترندات\n- قِيس النتائج: الشركات كتحب الأرقام\n- اتقن الأدوات: Google Analytics, SEMrush, Canva\n\n**اقرأ أيضاً:** [المهن التقنية](/article/mihn-taqniya) | [العمل الحر](/article/al-amal-al-hur)',
'<h2>التسويق الرقمي في المغرب</h2><h3>مدير حسابات إعلانية</h3><p>يدير إعلانات Google وFacebook - الرواتب: 8000 - 20,000 درهم</p><h3>خبير SEO</h3><p>يحسن ترتيب المواقع في Google - الرواتب: 10,000 - 25,000 درهم</h3><h3>كاتب المحتوى</h3><p>يكتب مقالات وأوصاف - الرواتب: 4000 - 10,000 درهم</p><p><strong>اقرأ أيضاً:</strong> المهن التقنية | العمل الحر</p>',
'published', NOW(),
'التسويق الرقمي في المغرب 2026 | دليل شامل',
'التسويق الرقمي صار من أهم المهارات.',
