-- 11. المقال العاشر: نصائح لخريجي الجامعات
INSERT INTO articles (title, slug, excerpt, content, content_html, status, published_at, meta_title, meta_description, reading_time, category_id, author_id)
SELECT 'نصائح لخريجي الجامعات في المغرب: كيفاش تلقى الخدمة', 'nusaih-kharrijin',
'خريج جامعي وكتلقى صعوبة في إيجاد عمل؟ خطوات عملية باش تلقى الخدمة في أول 6 أشهر.',
E'# نصائح لخريجي الجامعات في المغرب\n\nكل سنة كيخرجو آلاف الطلاب من الجامعات المغربية، وكيعثرون على صعوبة في إيجاد أول عمل. هادشي عادي، لكن فيه حلول.\n\n## خطوات عملية لتلقى الخدمة\n\n### 1. حسّن سيرتك الذاتية\n- اكتب سيرة ذاتية مختصرة وواضحة\n- خصصها لكل وظيفة تقدم لها\n- استخدم PDF مش Word\n\n### 2. سجّل في مواقع التوظيف\n- LinkedIn: المهم جداً\n- Indeed Morocco\n- Bayt.com\n- Tanqeeb\n\n### 3. استغل العلاقات\nالأقارب والأصدقاء ممكن يعرفو حيتوظفون. خبرهم إنك كتقلب على خدمة.\n\n### 4. تدرب في الشركات\nحتى لو بدون أجر، الخبرة مهمة وممكن يتوظفونك بعد التدريب.\n\n### 5. تعلم مهارة جديدة\nالبرمجة، التسويق الرقمي، التصميم الجرافيكي، لغة أجنبية\n\n## القطاعات اللي كتوظف بزاف\n\n- قطاع البنوك والتأمين\n- قطاع السياحة والضيافة\n- قطاع automotive\n- قطاع البناء\n\n## نصائح مهمة\n\n- لا تيأس: التوظيف كياخد وقت\n- كن صبور: أول خدمة صعبة، لكن بعدها غادي تسهل\n- استثمر في راسك: تعلم مهارة جديدة كل شهر\n- كون منظّم: خلق جدول زمني للبحث عن العمل\n\n**اقرأ أيضاً:** [كتابة السيرة الذاتية](/article/kitaba-sirat-dhatia) | [استعداد للمقابلة](/article/i-dad-muqabala-wazifiya) | [الوظائف الأكثر طلباً](/article/wadifa-maghreb-2026)',
'<h2>نصائح لخريجي الجامعات</h2><h3>خطوات عملية</h3><ul><li>حسّن سيرتك الذاتية</li><li>سجّل في مواقع التوظيف</li><li>استغل العلاقات</li><li>تدرب في الشركات</li><li>تعلم مهارة جديدة</li></ul><h3>القطاعات اللي كتوظف بزاف</h3><ul><li>قطاع البنوك والتأمين</li><li>قطاع السياحة والضيافة</li><li>قطاع automotive</li><li>قطاع البناء</li></ul><p><strong>اقرأ أيضاً:</strong> كتابة السيرة الذاتية | استعداد للمقابلة | الوظائف الأكثر طلباً</p>',
'published', NOW(),
'نصائح لخريجي الجامعات في المغرب 2026',
